void nfp_flower_stats_meter_request_all ( struct nfp_flower_priv * fl_priv ) { struct nfp_meter_entry * meter_entry = NULL ; struct rhashtable_iter iter ; mutex_lock ( & fl_priv -> meter_stats_lock ) ; rhashtable_walk_enter ( & fl_priv -> meter_table , & iter ) ; rhashtable_walk_start ( & iter ) ; while ( ( meter_entry = rhashtable_walk_next ( & iter ) ) != NULL ) { if ( IS_ERR ( meter_entry ) ) { continue ; } } rhashtable_walk_stop ( & iter ) ; rhashtable_walk_exit ( & iter ) ; mutex_unlock ( & fl_priv -> meter_stats_lock ) ; } 